	          const std::vector<char> basic =
	              use_highs_ledger ? std::vector<char>{}
	                               : bc_original_basic_mask(n, basis);
	          int basic_cols = 0;
	          int lower_cols = 0;
	          int upper_cols = 0;
	          int zero_cols = 0;
	          int other_cols = 0;
	          int fractional = 0;
	          std::uint64_t frontier_hash = std::uint64_t{0x4849474853465241};
